import React, { useState } from "react";
import List from "@mui/material/List";
import ListItem from "@mui/material/ListItem";
import TeamDisplay from "./TeamDisplay";
import Players from "./Players";
import { useRoundContext } from "../../contexts/RoundContext";
import { LETTERS, Team } from "../../types/Round";

export interface Player {
	name: string;
	isCaptain?: boolean;
}

const reletter = (teams: Team[]) =>
	teams.map((team, idx) => ({ ...team, letter: LETTERS[idx] }));

const Teams = () => {
	const { teams, setTeams } = useRoundContext();

	const [playerEditingTeam, setPlayerEditingTeam] = useState<
		number | undefined
	>();

	if (playerEditingTeam !== undefined) {
		return (
			<Players
				done={() => setPlayerEditingTeam(undefined)}
				letter={LETTERS[playerEditingTeam]}
				team={teams[playerEditingTeam].name}
				players={teams[playerEditingTeam].players}
				setPlayers={(newPlayers: Player[]) => {
					setTeams([
						...teams.slice(0, playerEditingTeam),
						{
							...teams[playerEditingTeam],
							players: newPlayers
						},
						...teams.slice(playerEditingTeam + 1)
					]);
				}}
			/>
		);
	} else {
		return (
			<List className="teams">
				{teams.map((team, idx) => (
					<React.Fragment key={idx}>
						<TeamDisplay
							addPlayers={() => setPlayerEditingTeam(idx)}
							letter={LETTERS[idx]}
							moveDown={
								idx < teams.length - 1
									? () => {
											const newTeams = [
												...teams.slice(0, idx),
												teams[idx + 1],
												team,
												...teams.slice(idx + 2)
											];
											setTeams(reletter(newTeams));
										}
									: undefined
							}
							moveUp={
								idx > 0
									? () => {
											setTeams(
												reletter([
													...teams.slice(0, idx - 1),
													team,
													teams[idx - 1],
													...teams.slice(idx + 1)
												])
											);
										}
									: undefined
							}
							team={team.name}
						/>
						<List className="print-only">
							{team.players.map((player, playerIdx) => {
								if (player?.name && player.name.trim() !== "") {
									return (
										<ListItem
											key={`${playerIdx}${player.name}`}
											style={{ listStyle: "none" }}
										>
											<span style={{ marginRight: "1em" }}>
												{LETTERS[idx]}
												{playerIdx + 1}
											</span>
											{player.isCaptain ? "*" : ""}
											{player.name}
										</ListItem>
									);
								} else {
									return <React.Fragment key={playerIdx}></React.Fragment>;
								}
							})}
						</List>
					</React.Fragment>
				))}
			</List>
		);
	}
};

export default Teams;
